def load_data_csv(data_file):
      data = pd.read_csv(data_file,delimiter=',',on_bad_lines='skip')
      data = pd.read_csv(data_file,converters={"cloud_points": lambda x: x.strip("[]").split(", ")},on_bad_lines='skip')
      return data

def process_data_csv(data_frame):

   raw_data = []
   xyz=[]
   #print('Data frame',data_frame)
   data_frame = data_frame.reset_index()

   for index, data in data_frame.iterrows():
      raw_data.append(ast.literal_eval(data[2])) # convert str list into list

      #print('raw data', raw_data[-1])
      #print('len of raw_data: ',len(raw_data[-1]))

      for i in range (len(raw_data[-1])):

         elevation = raw_data[-1][i][2]
         azimuth = raw_data[-1][i][1]
         doppler = raw_data[-1][i][2]
         Mrange = raw_data[-1][i][0]

         
         x = (Mrange * math.cos(elevation) * math.sin(azimuth))
         y = (Mrange * math.cos(elevation) * math.cos(azimuth))
         z = (Mrange * math.sin(elevation)) 
         #x = Mrange * math.cos(elevation) * math.sin(azimuth)
         #y = Mrange * math.cos(elevation) * math.cos(azimuth)
         #z = Mrange * math.sin(elevation)
         

         #if(x<=4  and x>=-4 and y<=5.5 and y>=1.5):
         xyz.append([x,y,z])
   
   return xyz

def xyz_to_pcd(xyz):

   pcd = o3d.geometry.PointCloud()
   pcd.points = o3d.utility.Vector3dVector(xyz)
   o3d.io.write_point_cloud("data_x.pcd", pcd)


